-- 013_novacurr_timetable_import.sql
-- Generated from Nova-T export files: NOVACURR.TXT + TBTRA-F.DAT
-- Imports real teaching groups (classes) and their weekly timetable slots.
-- ASSUMPTION: period-slot numbers decoded as slot=(period-1)*5+day (Mon-Fri, 9 periods/day).
--             Verify a few groups against the real timetable and adjust slot_to_day_period() logic if needed.

-- 1. Allow Year 12
ALTER TABLE students DROP CONSTRAINT IF EXISTS students_year_group_check;
ALTER TABLE students ADD CONSTRAINT students_year_group_check CHECK (year_group BETWEEN 7 AND 12);

-- 2. Track the imported teaching-group code + staff code on classes/staff so re-imports can upsert cleanly
ALTER TABLE classes ADD COLUMN IF NOT EXISTS class_code TEXT UNIQUE;
ALTER TABLE staff ADD COLUMN IF NOT EXISTS staff_code TEXT UNIQUE;

-- 2b. Clean up any partial/duplicate rows from a previous failed run, then enforce real uniqueness
DELETE FROM staff a USING staff b WHERE a.staff_id > b.staff_id AND a.staff_code = b.staff_code AND a.staff_code IS NOT NULL;
ALTER TABLE staff DROP CONSTRAINT IF EXISTS staff_staff_code_key;
ALTER TABLE staff ADD CONSTRAINT staff_staff_code_key UNIQUE (staff_code);

-- classes.class_code was already declared UNIQUE above, but clean up duplicates just in case of a partial rerun
DELETE FROM classes a USING classes b WHERE a.class_id > b.class_id AND a.class_code = b.class_code AND a.class_code IS NOT NULL;

DELETE FROM subjects a USING subjects b WHERE a.subject_id > b.subject_id AND a.subject_name = b.subject_name;
ALTER TABLE subjects DROP CONSTRAINT IF EXISTS subjects_subject_name_key;
ALTER TABLE subjects ADD CONSTRAINT subjects_subject_name_key UNIQUE (subject_name);

-- 3. Staff placeholders (rename first_name/last_name later in the Staff screen)

-- 4. Subjects (from Nova-T curriculum block categories)

-- 5. Teaching groups as classes

-- 6. Timetable slots (day/period decoded from the Nova-T period-slot number, see assumption above)
-- Clear only the slots for classes we are re-importing, so hand-added slots elsewhere are untouched
DELETE FROM timetable_slots WHERE class_id IN (SELECT class_id FROM classes WHERE class_code IS NOT NULL);
